type CredentialStatus uint8

const (
	CredentialStatus_Ok                CredentialStatus = 0
	CredentialStatus_TtlInvalid        CredentialStatus = 1
	CredentialStatus_TtlTooLong        CredentialStatus = 2
	CredentialStatus_BadPubkey         CredentialStatus = 3
	CredentialStatus_ScopeNotPermitted CredentialStatus = 4
	CredentialStatus_SpawnLimit        CredentialStatus = 5
	CredentialStatus_NotCredential     CredentialStatus = 6
	CredentialStatus_NoSuchTask        CredentialStatus = 7
	CredentialStatus_MaskedCap         CredentialStatus = 8
	CredentialStatus_BadName           CredentialStatus = 9
)

func (e CredentialStatus) String() string {
	switch e {
	case CredentialStatus_Ok:
		return "ok"
	case CredentialStatus_TtlInvalid:
		return "ttl_invalid"
	case CredentialStatus_TtlTooLong:
		return "ttl_too_long"
	case CredentialStatus_BadPubkey:
		return "bad_pubkey"
	case CredentialStatus_ScopeNotPermitted:
		return "scope_not_permitted"
	case CredentialStatus_SpawnLimit:
		return "spawn_limit"
	case CredentialStatus_NotCredential:
		return "not_credential"
	case CredentialStatus_NoSuchTask:
		return "no_such_task"
	case CredentialStatus_MaskedCap:
		return "masked_cap"
	case CredentialStatus_BadName:
		return "bad_name"
	default:
		return fmt.Sprintf("CredentialStatus(%d)", e)
	}
}

